namespace ApiVault.Core.DTOs;

/// <summary>An encrypted VEK wrapper. byte[] values travel as base64 in JSON.</summary>
public record KeyWrapperRequest(string WrapperType, byte[] EncryptedVaultKey, byte[] Nonce, byte[] AuthTag, int KeyVersion);

public record KeyWrapperResponse(Guid Id, Guid VaultId, string WrapperType, byte[] EncryptedVaultKey,
    byte[] Nonce, byte[] AuthTag, int KeyVersion, DateTime CreatedAt);

/// <summary>
/// The vault Id is generated by the browser because it is bound into the AES-GCM AAD of the key wrappers.
/// </summary>
public record CreateVaultRequest(
    Guid Id,
    string Name,
    string? Description,
    string KdfAlgorithm,
    byte[] KdfSalt,
    string KdfParameters,
    string EncryptionAlgorithm,
    int KeyVersion,
    KeyWrapperRequest PasswordWrapper,
    KeyWrapperRequest? RecoveryWrapper);

public record UpdateVaultRequest(string Name, string? Description);

public record VaultResponse(Guid Id, string Name, string? Description, string KdfAlgorithm, byte[] KdfSalt,
    string KdfParameters, string EncryptionAlgorithm, int KeyVersion, DateTime CreatedAt, DateTime? ModifiedAt);
